// NoteMutation represents an operation that mutates the Note nodes in the graph.
type NoteMutation struct {
	config
	op            Op
	typ           string
	id            *uuid.UUID
	body          *string
	clearedFields map[string]struct{}
	docs          map[uuid.UUID]struct{}
	removeddocs   map[uuid.UUID]struct{}
	cleareddocs   bool
	done          bool
	oldValue      func(context.Context) (*Note, error)
	predicates    []predicate.Note
}

var _ ent.Mutation = (*NoteMutation)(nil)

// noteOption allows management of the mutation configuration using functional options.
type noteOption func(*NoteMutation)

// newNoteMutation creates new mutation for the Note entity.
func newNoteMutation(c config, op Op, opts ...noteOption) *NoteMutation {
	m := &NoteMutation{
		config:        c,
		op:            op,
		typ:           TypeNote,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withNoteID sets the ID field of the mutation.
func withNoteID(id uuid.UUID) noteOption {
	return func(m *NoteMutation) {
		var (
			err   error
			once  sync.Once
			value *Note
		)
		m.oldValue = func(ctx context.Context) (*Note, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().Note.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withNote sets the old Note of the mutation.
func withNote(node *Note) noteOption {
	return func(m *NoteMutation) {
		m.oldValue = func(context.Context) (*Note, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

// Client returns a new `ent.Client` from the mutation. If the mutation was
// executed in a transaction (ent.Tx), a transactional client is returned.
func (m NoteMutation) Client() *Client {
	client := &Client{config: m.config}
	client.init()
	return client
}

// Tx returns an `ent.Tx` for mutations that were executed in transactions;
// it returns an error otherwise.
func (m NoteMutation) Tx() (*Tx, error) {
	if _, ok := m.driver.(*txDriver); !ok {
		return nil, errors.New("softdeleteent: mutation is not running in a transaction")
	}
	tx := &Tx{config: m.config}
	tx.init()
	return tx, nil
}

// SetID sets the value of the id field. Note that this
// operation is only accepted on creation of Note entities.
func (m *NoteMutation) SetID(id uuid.UUID) {
	m.id = &id
}

// ID returns the ID value in the mutation. Note that the ID is only available
// if it was provided to the builder or after it was returned from the database.
func (m *NoteMutation) ID() (id uuid.UUID, exists bool) {
	if m.id == nil {
		return
	}
	return *m.id, true
}

// IDs queries the database and returns the entity ids that match the mutation's predicate.
// That means, if the mutation is applied within a transaction with an isolation level such
// as sql.LevelSerializable, the returned ids match the ids of the rows that will be updated
// or updated by the mutation.
func (m *NoteMutation) IDs(ctx context.Context) ([]uuid.UUID, error) {
	switch {
	case m.op.Is(OpUpdateOne | OpDeleteOne):
		id, exists := m.ID()
		if exists {
			return []uuid.UUID{id}, nil
		}
		fallthrough
	case m.op.Is(OpUpdate | OpDelete):
		return m.Client().Note.Query().Where(m.predicates...).IDs(ctx)
	default:
		return nil, fmt.Errorf("IDs is not allowed on %s operations", m.op)
	}
}

// SetBody sets the "body" field.
func (m *NoteMutation) SetBody(s string) {
	m.body = &s
}

// Body returns the value of the "body" field in the mutation.
func (m *NoteMutation) Body() (r string, exists bool) {
	v := m.body
	if v == nil {
		return
	}
	return *v, true
}

// OldBody returns the old "body" field's value of the Note entity.
// If the Note object wasn't provided to the builder, the object is fetched from the database.
// An error is returned if the mutation operation is not UpdateOne, or the database query fails.
func (m *NoteMutation) OldBody(ctx context.Context) (v string, err error) {
	if !m.op.Is(OpUpdateOne) {
		return v, errors.New("OldBody is only allowed on UpdateOne operations")
	}
	if m.id == nil || m.oldValue == nil {
		return v, errors.New("OldBody requires an ID field in the mutation")
	}
	oldValue, err := m.oldValue(ctx)
	if err != nil {
		return v, fmt.Errorf("querying old value for OldBody: %w", err)
	}
	return oldValue.Body, nil
}

// ResetBody resets all changes to the "body" field.
func (m *NoteMutation) ResetBody() {
	m.body = nil
}

// AddDocIDs adds the "docs" edge to the Doc entity by ids.
func (m *NoteMutation) AddDocIDs(ids ...uuid.UUID) {
	if m.docs == nil {
		m.docs = make(map[uuid.UUID]struct{})
	}
	for i := range ids {
		m.docs[ids[i]] = struct{}{}
	}
}

// ClearDocs clears the "docs" edge to the Doc entity.
func (m *NoteMutation) ClearDocs() {
	m.cleareddocs = true
}

// DocsCleared reports if the "docs" edge to the Doc entity was cleared.
func (m *NoteMutation) DocsCleared() bool {
	return m.cleareddocs
}

// RemoveDocIDs removes the "docs" edge to the Doc entity by IDs.
func (m *NoteMutation) RemoveDocIDs(ids ...uuid.UUID) {
	if m.removeddocs == nil {
		m.removeddocs = make(map[uuid.UUID]struct{})
	}
	for i := range ids {
		delete(m.docs, ids[i])
		m.removeddocs[ids[i]] = struct{}{}
	}
}

// RemovedDocs returns the removed IDs of the "docs" edge to the Doc entity.
func (m *NoteMutation) RemovedDocsIDs() (ids []uuid.UUID) {
	for id := range m.removeddocs {
		ids = append(ids, id)
	}
	return
}

// DocsIDs returns the "docs" edge IDs in the mutation.
func (m *NoteMutation) DocsIDs() (ids []uuid.UUID) {
	for id := range m.docs {
		ids = append(ids, id)
	}
	return
}

// ResetDocs resets all changes to the "docs" edge.
func (m *NoteMutation) ResetDocs() {
	m.docs = nil
	m.cleareddocs = false
	m.removeddocs = nil
}

// Where appends a list predicates to the NoteMutation builder.
